<?php
session_start();
require_once __DIR__.'/../lead-engine/config.php';
require_once __DIR__.'/../lead-engine/goliath-db.php';
if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/?next='.rawurlencode($_SERVER['REQUEST_URI']??'/dashboard/goliath-workbench.php'));exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function rows($sql,$p=[]){try{return gdb_all($sql,$p)?:[];}catch(Throwable $e){return [];}}
function one($sql,$p=[]){try{return gdb_one($sql,$p)?:[];}catch(Throwable $e){return [];}}
$view=$_GET['view']??'all'; $archive=(int)($_GET['archive']??0); $exec=strtolower($_GET['exec']??'');
$groups=[
'videos'=>[['scorsese','columbo','mozart'],['video_package','thumbnail_package','youtube_growth_package','media_package','ai_video_generation','mp4']],
'blogs'=>[['shakespeare'],['publish_ready_blog','blog_article','landing_page','weekly_market_report','social_copy_package']],
'leads'=>[['scout','jessica'],['lead_list','verified_lead_csv','contact_enrichment_report','crm_enrichment','lead_score_report']],
'email'=>[['jessica','prospector','pandora'],['outreach_email_campaign','email_campaign','speaking_opportunity_pipeline','sponsor_pipeline','partnership_package']],
'seo'=>[['einstein','shakespeare'],['seo_audit','seo_schema_package','seo_aeo_growth','research_source_pack']],
'money'=>[['rockefeller','prospector','pandora'],['revenue_plan','sponsor_pipeline','speaking_opportunity_pipeline']]
];
$where=[];$p=[];
if($archive){$where[]="(COALESCE(evidence_status,'')='legacy_archive' OR deliverable_type IN ('legacy_completion','legacy_brief') OR title LIKE '%Production Mission:%')";}
else{$where[]="COALESCE(evidence_status,'')<>'legacy_archive'";$where[]="COALESCE(deliverable_type,'') NOT IN ('legacy_completion','legacy_brief')";$where[]="title NOT LIKE '%Production Mission:%'";$where[]="COALESCE(output_summary,'') NOT LIKE 'Legacy worker completion backfilled%'";}
if($exec){$where[]="executive_key=?";$p[]=$exec;}
elseif(isset($groups[$view])){[$es,$ts]=$groups[$view];$parts=[];$parts[]="executive_key IN (".implode(',',array_fill(0,count($es),'?')).")";foreach($es as $x)$p[]=$x;$parts[]="deliverable_type IN (".implode(',',array_fill(0,count($ts),'?')).")";foreach($ts as $x)$p[]=$x;$where[]="(".implode(' OR ',$parts).")";}
$assets=rows("SELECT * FROM goliath_deliverables WHERE ".implode(' AND ',$where)." ORDER BY created_at DESC,id DESC LIMIT 120",$p);
$counts=['all'=>0,'videos'=>0,'blogs'=>0,'leads'=>0,'email'=>0,'seo'=>0,'money'=>0,'archive'=>0];
$base="COALESCE(evidence_status,'')<>'legacy_archive' AND COALESCE(deliverable_type,'') NOT IN ('legacy_completion','legacy_brief') AND title NOT LIKE '%Production Mission:%' AND COALESCE(output_summary,'') NOT LIKE 'Legacy worker completion backfilled%'";
$counts['all']=(int)((one("SELECT COUNT(*) c FROM goliath_deliverables WHERE $base")?:['c'=>0])['c']);
foreach($groups as $k=>$g){[$es,$ts]=$g;$params=[];$parts=[];$parts[]="executive_key IN (".implode(',',array_fill(0,count($es),'?')).")";foreach($es as $x)$params[]=$x;$parts[]="deliverable_type IN (".implode(',',array_fill(0,count($ts),'?')).")";foreach($ts as $x)$params[]=$x;$counts[$k]=(int)((one("SELECT COUNT(*) c FROM goliath_deliverables WHERE $base AND (".implode(' OR ',$parts).")",$params)?:['c'=>0])['c']);}
$counts['archive']=(int)((one("SELECT COUNT(*) c FROM goliath_deliverables WHERE COALESCE(evidence_status,'')='legacy_archive' OR deliverable_type IN ('legacy_completion','legacy_brief') OR title LIKE '%Production Mission:%'")?:['c'=>0])['c']);
$execs=['scout'=>'Scout','jessica'=>'Jessica','scorsese'=>'Scorsese','shakespeare'=>'Shakespeare','columbo'=>'Columbo','einstein'=>'Einstein','prospector'=>'Prospector','pandora'=>'Pandora','rockefeller'=>'Rockefeller','mozart'=>'Mozart','goliath'=>'Goliath'];
$title=$archive?'Old Brief Archive':($exec?($execs[$exec]??ucfirst($exec)).' Workspace':ucwords(str_replace('_',' ',$view==='all'?'All Real Assets':$view)));
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Goliath Workbench</title><link rel="stylesheet" href="/dashboard/assets/goliath-v33.css?v=33"><link rel="stylesheet" href="/dashboard/assets/goliath-v45-final.css?v=456"><style>body{background:#030712;color:#fff}.layout{display:grid;grid-template-columns:300px 1fr;gap:14px}.panelLite{background:#07111f;border:1px solid #ffffff22;border-radius:18px;padding:14px}.menu a{display:flex;justify-content:space-between;color:#fff;text-decoration:none;background:#0f172a;border:1px solid #ffffff22;border-radius:14px;padding:11px;margin:7px 0;font-weight:900}.menu a.active,.menu a:hover{border-color:#d4af37}.menu b{color:#d4af37}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:14px}.card{background:#07111f;border:1px solid #ffffff22;border-radius:18px;padding:14px}.card h3{color:#f5d48b;margin:0}.meta{color:#94a3b8;font-size:12px}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.btn.small{padding:8px 10px;font-size:12px}.empty{padding:40px;text-align:center;color:#94a3b8}@media(max-width:950px){.layout{grid-template-columns:1fr}}</style></head><body><div class="shell"><?php @require __DIR__.'/includes/goliath-sidebar-v33.php'; ?><main class="main"><section class="top"><div><h1>Goliath Workbench</h1><p>Real assets only. Old text briefs are hidden in the archive.</p></div><div class="brandbar"><a class="btn dark" href="/dashboard/goliath-missions.php">Team Missions</a><a class="btn" href="/dashboard/scorsese-media-center.php">Videos</a></div></section><section class="layout"><aside class="panelLite menu"><h2>Asset Menu</h2><?php foreach(['all'=>'All Real Assets','videos'=>'Videos & Thumbnails','blogs'=>'Blogs & Pages','leads'=>'Leads & Call Lists','email'=>'Emails & Outreach','seo'=>'SEO / AEO Fixes','money'=>'Money Opportunities'] as $k=>$label): ?><a class="<?=($view===$k&&!$archive&&!$exec)?'active':''?>" href="/dashboard/goliath-workbench.php<?=($k==='all'?'':'?view='.$k)?>"><span><?=h($label)?></span><b><?=h($counts[$k])?></b></a><?php endforeach; ?><a class="<?=$archive?'active':''?>" href="?archive=1"><span>Old Brief Archive</span><b><?=h($counts['archive'])?></b></a><hr style="border-color:#ffffff18"><h3>Executive Workspaces</h3><?php foreach($execs as $k=>$label): $href=$k==='scorsese'?'/dashboard/scorsese-media-center.php':'/dashboard/goliath-workbench.php?exec='.$k; ?><a href="<?=h($href)?>"><span><?=h($label)?></span><b>›</b></a><?php endforeach;?></aside><main class="panelLite"><h2><?=h($title)?> <span><?=count($assets)?> shown</span></h2><?php if(!count($assets)):?><div class="empty"><h2>No real assets here yet.</h2><p>Good: old summaries are hidden. New V78 asset-contract outputs will land here.</p><a class="btn" href="?archive=1">Open Old Brief Archive</a></div><?php endif;?><div class="grid"><?php foreach($assets as $a):?><div class="card"><h3><?=h(ucfirst($a['executive_key']))?> — <?=h($a['title'])?></h3><div class="meta">#<?=h($a['id'])?> · <?=h($a['deliverable_type'])?> · <?=h($a['created_at'])?></div><p><?=h(mb_substr(strip_tags($a['output_summary']??''),0,280))?></p><div class="actions"><a class="btn small" href="/dashboard/goliath-deliverables.php?deliverable_id=<?=h($a['id'])?>">View Details</a><?php if(!empty($a['output_url'])):?><a class="btn small" target="_blank" href="<?=h($a['output_url'])?>">Preview Asset</a><?php endif;?><button class="btn small">Ask for Changes</button><button class="btn small">Prepare Social Post</button></div></div><?php endforeach;?></div></main></section></main></div></body></html>